import unittest

from solution import compose_theme


class ComposeThemeTests(unittest.TestCase):
    def test_recursive_merge_replacement_and_deletion(self):
        base = {
            "colors": {"primary": "blue", "secondary": "gray"},
            "fonts": ["sans"],
            "remove": {"x": 1},
        }
        overrides = {
            "colors": {"primary": "red", "accent": "gold"},
            "fonts": ["serif"],
            "remove": None,
            "new": {"enabled": True},
        }
        self.assertEqual(compose_theme(base, overrides), {
            "colors": {"primary": "red", "secondary": "gray", "accent": "gold"},
            "fonts": ["serif"],
            "new": {"enabled": True},
        })

    def test_none_deletes_only_at_merge_level(self):
        base = {"outer": {"keep": 1, "drop": 2}, "missing": 3}
        overrides = {"outer": {"drop": None}, "absent": None}
        self.assertEqual(compose_theme(base, overrides), {"outer": {"keep": 1}, "missing": 3})

    def test_no_mutation_or_mutable_aliases(self):
        base = {
            "from_base": {"items": [1, {"set": {2}}]},
            "tuple": ([3],),
        }
        overrides = {"from_override": {"items": [4]}, "replacement": [{"x": 5}]}
        result = compose_theme(base, overrides)

        self.assertEqual(base, {
            "from_base": {"items": [1, {"set": {2}}]},
            "tuple": ([3],),
        })
        self.assertEqual(overrides, {
            "from_override": {"items": [4]}, "replacement": [{"x": 5}]
        })

        result["from_base"]["items"][1]["set"].add(9)
        result["tuple"][0].append(6)
        result["from_override"]["items"].append(7)
        result["replacement"][0]["x"] = 8
        self.assertEqual(base["from_base"]["items"][1]["set"], {2})
        self.assertEqual(base["tuple"], ([3],))
        self.assertEqual(overrides["from_override"]["items"], [4])
        self.assertEqual(overrides["replacement"], [{"x": 5}])

    def test_hashable_non_string_keys_and_empty_inputs(self):
        key = ("section", 1)
        self.assertEqual(compose_theme({key: {1: "old", 2: "keep"}}, {key: {1: "new"}}),
                         {key: {1: "new", 2: "keep"}})
        self.assertEqual(compose_theme({}, {}), {})
        self.assertEqual(compose_theme({"x": 1}, {}), {"x": 1})

    def test_top_level_arguments_must_be_dictionaries(self):
        for base, overrides in (([], {}), ({}, []), (None, {}), ({}, None)):
            with self.assertRaises(TypeError):
                compose_theme(base, overrides)


if __name__ == "__main__":
    unittest.main()

